const src = $json;

const manualReview = src?.decision?.manual_review_required === true || src?.titan_audit?.manual_review_required === true;
const title = src?.status?.title || src?.response?.title || 'Titan Support Review';
const category = src?.status?.category || src?.response?.category || 'unknown';
const severity = src?.status?.severity || src?.response?.severity || 'unknown';
const route = src?.decision?.route || 'unknown';
const action = src?.decision?.action || src?.titan_audit?.next_step_recommendation || 'review_required';
const confidence = src?.titan_audit?.confidence_score ?? src?.resolver?.confidence ?? 'unknown';
const safeToExecute = src?.titan_audit?.safe_to_execute ?? src?.execution?.allowed ?? false;

return [
  {
    json: {
      should_alert: manualReview,
      alert_title: manualReview ? 'Manual review required' : 'No manual review required',
      titan_title: title,
      category,
      severity,
      route,
      action,
      confidence,
      safe_to_execute: safeToExecute,
      message: manualReview
        ? `Titan flagged this workflow step for manual review. Category: ${category}. Action: ${action}.`
        : `Titan did not require manual review. Category: ${category}. Action: ${action}.`,
      titan_response: src
    }
  }
];
